CREATE TABLE IF NOT EXISTS coin_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL CHECK(reason IN ('session','purchase')), ref TEXT NOT NULL, created TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(user_id, reason, ref));
CREATE TABLE IF NOT EXISTS wardrobe(user_id INTEGER NOT NULL, item_id TEXT NOT NULL, bought_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(user_id, item_id));
CREATE TABLE IF NOT EXISTS avatar(user_id INTEGER PRIMARY KEY, skin INTEGER NOT NULL DEFAULT 1, hair INTEGER NOT NULL DEFAULT 1, hair_color INTEGER NOT NULL DEFAULT 1, outfit TEXT NOT NULL DEFAULT 'outfit:casual', accessory TEXT, name TEXT);
CREATE TABLE IF NOT EXISTS town_plots(id INTEGER PRIMARY KEY AUTOINCREMENT, district INTEGER NOT NULL, slot INTEGER NOT NULL, user_id INTEGER UNIQUE, UNIQUE(district, slot));
CREATE TABLE IF NOT EXISTS houses(user_id INTEGER PRIMARY KEY, plot_id INTEGER NOT NULL, name TEXT, size TEXT NOT NULL DEFAULT 'house:hut', roof TEXT NOT NULL DEFAULT 'roof:red', wall TEXT NOT NULL DEFAULT 'wall:plaster', door TEXT NOT NULL DEFAULT 'door:wood', floor TEXT NOT NULL DEFAULT 'floor:wood', wallpaper TEXT NOT NULL DEFAULT 'wallpaper:cream', door_mode TEXT NOT NULL DEFAULT 'knock' CHECK(door_mode IN ('knock','open','closed')));
CREATE TABLE IF NOT EXISTS house_items(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, item_id TEXT NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL, flip INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS house_access(house_user INTEGER NOT NULL, guest INTEGER NOT NULL, expires INTEGER NOT NULL, PRIMARY KEY(house_user, guest));
CREATE TABLE IF NOT EXISTS user_blocks(blocker INTEGER NOT NULL, blocked INTEGER NOT NULL, PRIMARY KEY(blocker, blocked));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT, reporter INTEGER NOT NULL, target INTEGER NOT NULL, reason TEXT, text TEXT, created TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS session_active(session_id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, started INTEGER NOT NULL, last_ping INTEGER NOT NULL, active_secs INTEGER NOT NULL DEFAULT 0, verified_secs INTEGER NOT NULL DEFAULT 0, last_ok INTEGER NOT NULL, misses INTEGER NOT NULL DEFAULT 0, paused INTEGER NOT NULL DEFAULT 0, ended INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS checkins(id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, user_id INTEGER NOT NULL, due INTEGER NOT NULL, expires INTEGER NOT NULL, answered INTEGER);
CREATE TABLE IF NOT EXISTS pantry(user_id INTEGER NOT NULL, item_id TEXT NOT NULL, qty INTEGER NOT NULL DEFAULT 0 CHECK(qty >= 0), PRIMARY KEY(user_id, item_id));
CREATE TABLE IF NOT EXISTS user_status(user_id INTEGER PRIMARY KEY, fed_until INTEGER NOT NULL DEFAULT 0, fed_item TEXT);
CREATE INDEX IF NOT EXISTS idx_ledger_user ON coin_ledger(user_id);
CREATE INDEX IF NOT EXISTS idx_wardrobe_user ON wardrobe(user_id);
CREATE INDEX IF NOT EXISTS idx_house_items_user ON house_items(user_id);
CREATE INDEX IF NOT EXISTS idx_access_house ON house_access(house_user);
CREATE INDEX IF NOT EXISTS idx_access_guest ON house_access(guest);
CREATE INDEX IF NOT EXISTS idx_blocks_blocker ON user_blocks(blocker);
CREATE INDEX IF NOT EXISTS idx_reports_reporter ON reports(reporter);
CREATE INDEX IF NOT EXISTS idx_active_user ON session_active(user_id);
CREATE INDEX IF NOT EXISTS idx_checkins_user ON checkins(user_id);
CREATE INDEX IF NOT EXISTS idx_checkins_session ON checkins(session_id);
CREATE INDEX IF NOT EXISTS idx_pantry_user ON pantry(user_id);
